import { marked } from "./lib/marked.esm.js";
const cases = [
  "`a\\` *b*",
  "`a\\` *b* `c`",
  "`a\\` *b* c",
  "`a\\` *b* `c`",
  "`a\\`x *b*",
  "`a\\` x *b* `c`",
  "`a` *b* `c\\`",
  "x \\` *b* `c`",
  "`a\\` *b*`c`",
  "`a\\` **b** `c`",
  "`a\\` ~~b~~ `c`",
  "`a\\` [b](u) `c`",
];
for (const s of cases) {
  console.log(JSON.stringify(s), " => ", JSON.stringify(marked.parseInline(s)));
}

