import { Lexer, marked } from "./lib/marked.esm.js";
const cases = [
  "Use `C:\\Users\\` for **home** and `D:\\` for data.",
  "`a\\` *b* `c`",
  "`a\\b\\`",
  "`a\\b`",
  "`a\\`",
  "x `\\` **b**",
];
for (const s of cases) {
  const toks = Lexer.lex(s)[0].tokens;
  console.log(JSON.stringify(s), "\n  raws:", JSON.stringify(toks.map((x) => x.raw)), "\n  html:", JSON.stringify(marked.parse(s)));
}

