  + '|[^*]+(?=[^*])'
  + '|(?!\\*)PUNCT(\\*+)(?=[\\s]|$)'
  + '|NPS(\\*+)(?!\\*)(?=PSP|$)'
  + '|(?!\\*)PSP(\\*+)(?=NPS)'
  + '|[\\s](\\*+)(?!\\*)(?=PUNCT)'
  + '|(?!\\*)PUNCT(\\*+)(?!\\*)(?=PUNCT)'
  + '|NPS(\\*+)(?=NPS)';
const P = '[\\p{P}\\p{S}]';
const PSP = '[\\s\\p{P}\\p{S}]';
const NPS = '[^\\s\\p{P}\\p{S}]';
const re = new RegExp(core.replaceAll('PUNCT', P).replaceAll('PSP', PSP).replaceAll('NPS', NPS), 'gu');
for (const s of ['b* `c`', 'b* c', 'b* ++c`', 'b* `c`', 'b* ++c`']) {
  re.lastIndex = 0;
  const out = [];
