const orig = Tokenizer.prototype.emStrong;
Tokenizer.prototype.emStrong = function (src, masked, prev) {
  const r = orig.call(this, src, masked, prev);
  console.log("emStrong src=", JSON.stringify(src), "masked=", JSON.stringify(masked), "prev=", JSON.stringify(prev), "->", r && r.type);
  return r;
};
Lexer.lexInline("`a\\` *b* `c`");

